// 工程段只编码已经冻结的本人/部队/技艺来源，结构通过不代替早军籍和晚人物史验证。
#include "resident/checkpoint/checkpoint_decode_lifecycle.hpp"
#include "military_siege_engineering_codec.hpp"
#include "military_officer_codec.hpp"
#include "resident/domains/conditions/domain_codec_util.hpp"
#include "resident/storage/common_checkpoint.hpp"
#include <set>
namespace hanmo::resident::military_siege_engineering_codec {
namespace {
using namespace domain_codec;
const std::vector<StableId> sources{"unit_authored","army_formation","officer_assignment","field_assignment"};
Status shape(const MilitarySiegeEngineeringState& state){std::set<StableId> ids;for(const auto& p:state.preparations){if(!ids.insert(p.id).second)return common_failure("DuplicateSiegeEngineeringPreparation",p.id);auto valid=validate_military_siege_engineering_preparation_shape(p);if(!valid.ok)return valid;}auto fields=state.field_order;std::sort(fields.begin(),fields.end());return !fields.empty()&&fields!=FieldOrder{"preparations"}?common_failure("MilitarySiegeEngineeringStateShape"):common_success();}
Status emit_unit(ProjectionWriter& w,const MilitarySiegeEngineeringUnit& u){const auto n=static_cast<int>(u.command_source.kind);w.field("unit_id",u.unit_id);w.field("army_id",u.army_id);w.field("commander_actor_id",u.commander_actor_id);w.field("authored_actor_id",u.authored_actor_id);w.object("command_source",u.source_field_order,[&](auto& c){c.field("kind",sources[n]);c.field("id",u.command_source.id);return c.status();});w.field("fit_count",u.fit_count);w.field("experience",u.experience);w.field("level",u.level);w.sequence("causal_fact_ids",u.causal_fact_ids,[](auto& c,const auto& id){return c.field("",id);});w.order_fields(u.field_order);return w.status();}
Status emit_preparation(ProjectionWriter& w,const MilitarySiegeEngineeringPreparation& p,bool apply_order){w.field("id",p.id);w.field("siege_id",p.siege_id);w.field("topology_id",p.topology_id);w.field("previous_preparation_id",p.previous_preparation_id);w.field("from_tick",p.from_tick);w.field("to_tick",p.to_tick);w.field("round",p.round);w.sequence("units",p.units,[](auto& c,const auto& unit){return c.object("",[&](auto& d){return emit_unit(d,unit);});});if(apply_order)w.order_fields(p.field_order);return w.status();}
void decode_unit(const V& v,MilitarySiegeEngineeringUnit& u){const StableId at="siege_engineering/unit";boundary::fields(v,{"unit_id","army_id","commander_actor_id","authored_actor_id","command_source","fit_count","experience","level","causal_fact_ids"},{},at);u.field_order=boundary::order(v);u.unit_id=boundary::get_string(v,"unit_id",at);u.army_id=boundary::get_string(v,"army_id",at);u.commander_actor_id=boundary::get_string(v,"commander_actor_id",at);u.authored_actor_id=boundary::get_string(v,"authored_actor_id",at);u.fit_count=boundary::get_int(v,"fit_count",at);u.experience=boundary::get_int(v,"experience",at);u.level=boundary::get_int(v,"level",at);const auto& source=boundary::field(v,"command_source",at);boundary::fields(source,{"kind","id"},{},at+"/command_source");u.source_field_order=boundary::order(source);auto kind=boundary::get_string(source,"kind",at);auto found=std::find(sources.begin(),sources.end(),kind);if(found==sources.end())boundary::fail("MilitarySiegeEngineeringCommandSourceMismatch",at);u.command_source.kind=static_cast<MilitaryUnitCommandSourceKind>(found-sources.begin());u.command_source.id=boundary::get_string(source,"id",at);u.causal_fact_ids=boundary::strings(boundary::field(v,"causal_fact_ids",at),at);}
void decode_preparation(const V& v,MilitarySiegeEngineeringPreparation& p){const StableId at="siege_engineering/preparation";boundary::fields(v,{"id","siege_id","topology_id","previous_preparation_id","from_tick","to_tick","round","units"},{},at);p.field_order=boundary::order(v);p.id=boundary::get_string(v,"id",at);p.siege_id=boundary::get_string(v,"siege_id",at);p.topology_id=boundary::get_string(v,"topology_id",at);p.previous_preparation_id=boundary::get_string(v,"previous_preparation_id",at);p.from_tick=boundary::get_int(v,"from_tick",at);p.to_tick=boundary::get_int(v,"to_tick",at);p.round=boundary::get_int(v,"round",at);for(const auto& row:boundary::array(boundary::field(v,"units",at),at)){MilitarySiegeEngineeringUnit u;decode_unit(row,u);p.units.push_back(std::move(u));}}
Status walk_unit(CodecVisitor& c,MilitarySiegeEngineeringUnit& u){c.field("unit_id",u.unit_id);c.field("army_id",u.army_id);c.field("commander_actor_id",u.commander_actor_id);c.field("authored_actor_id",u.authored_actor_id);Integer kind=static_cast<int>(u.command_source.kind);c.field("source_kind",kind);if(kind<0||kind>3)return c.reject("MilitarySiegeEngineeringCommandSourceMismatch");u.command_source.kind=static_cast<MilitaryUnitCommandSourceKind>(kind);c.field("source_id",u.command_source.id);c.field("fit_count",u.fit_count);c.field("experience",u.experience);c.field("level",u.level);common_checkpoint::strings(c,"causal_fact_ids",u.causal_fact_ids);common_checkpoint::strings(c,"field_order",u.field_order);common_checkpoint::strings(c,"source_field_order",u.source_field_order);return c.status();}
Status walk_preparation(CodecVisitor& c,MilitarySiegeEngineeringPreparation& p){c.field("id",p.id);c.field("siege_id",p.siege_id);c.field("topology_id",p.topology_id);c.field("previous_preparation_id",p.previous_preparation_id);c.field("from_tick",p.from_tick);c.field("to_tick",p.to_tick);c.field("round",p.round);c.sequence("units",p.units,[](auto& child,auto& row){return walk_unit(child,row);});common_checkpoint::strings(c,"field_order",p.field_order);return c.status();}
}
Status emit_fields(ProjectionWriter& w,const MilitarySiegeEngineeringPreparation& value,bool apply_order){MilitarySiegeEngineeringState state;state.preparations.push_back(value);auto check=shape(state);if(!check.ok)return check;return emit_preparation(w,value,apply_order);}
BoundaryValue encode_fact(const MilitarySiegeEngineeringPreparation& value){BoundaryValue out;BoundaryProjectionWriter sink(out);auto check=sink.object("",[&](auto& c){return emit_fields(c,value);});if(check.ok)check=sink.finish();if(!check.ok)boundary::fail(check.error.original.code,check.error.original.path);return out;}
Outcome<MilitarySiegeEngineeringPreparation> decode_fact(const BoundaryValue& value){auto state=decode(BoundaryValue{BoundaryValue::Dict{{"preparations",BoundaryValue{BoundaryValue::Array{value}}}}});return state.ok?Outcome<MilitarySiegeEngineeringPreparation>{true,std::move(state.value.preparations.front()),{}}:Outcome<MilitarySiegeEngineeringPreparation>{false,{},state.error};}
Status emit_fields(ProjectionWriter& w,const MilitarySiegeEngineeringState& state){auto check=shape(state);if(!check.ok)return check;w.sequence("preparations",state.preparations,[](auto& c,const auto& p){return c.object("",[&](auto& row){return emit_preparation(row,p,true);});});w.order_fields(state.field_order);return w.status();}
BoundaryValue encode(const MilitarySiegeEngineeringState& value){BoundaryValue out;BoundaryProjectionWriter sink(out);auto check=sink.object("",[&](auto& c){return emit_fields(c,value);});if(check.ok)check=sink.finish();if(!check.ok)boundary::fail(check.error.original.code,check.error.original.path);return out;}
Outcome<MilitarySiegeEngineeringState> decode(const BoundaryValue& value){try{auto unique=military_officer_codec::validate_json_unique_keys(value);if(!unique.ok)return {false,{},unique.error};boundary::fields(value,{"preparations"},{},"siege_engineering");MilitarySiegeEngineeringState state;state.field_order=boundary::order(value);for(const auto& row:boundary::array(boundary::field(value,"preparations","siege_engineering"),"preparations")){MilitarySiegeEngineeringPreparation p;decode_preparation(row,p);state.preparations.push_back(std::move(p));}auto valid=shape(state);return valid.ok?Outcome<MilitarySiegeEngineeringState>{true,std::move(state),{}}:Outcome<MilitarySiegeEngineeringState>{false,{},valid.error};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Status visit(CodecVisitor& c,MilitarySiegeEngineeringState& state){if(c.military_codec_version!=17)return c.reject("MilitarySiegeEngineeringCodecRequired");c.sequence("preparations",state.preparations,[](auto& child,auto& row){return walk_preparation(child,row);});common_checkpoint::strings(c,"field_order",state.field_order);if(!c.status().ok)return c.status();auto valid=shape(state);return valid.ok?c.status():c.reject(valid.error.original.code,valid.error.original.path);}
}
